// El nodo Telegram Trigger procesa cada evento individualmente.
const elemento = $('Telegram Trigger').first().json;

let chat_id = "", user_id = "", first_name = "", text = "", chat_type = "", callback_query_id = "";

if (elemento.message) {
    chat_id    = String(elemento.message.chat.id);
    user_id    = String(elemento.message.from.id);
    first_name = elemento.message.from.first_name || "";
    text       = elemento.message.text || "";
    chat_type  = elemento.message.chat.type || "";
} else if (elemento.callback_query) {
    chat_id    = String(elemento.callback_query.message.chat.id);
    user_id    = String(elemento.callback_query.from.id);
    first_name = elemento.callback_query.from.first_name || "";
    text       = (elemento.callback_query.data || "").trim();
    // Limpieza de estado residual solicitada
    elemento.message = undefined;
    chat_type  = elemento.callback_query.message.chat.type || "";
    callback_query_id = String(elemento.callback_query.id);
}

const isGroup = (chat_type === 'group' || chat_type === 'supergroup');

// Solo dejamos pasar /estado o comandos de admin de la cocina si es un grupo
if (isGroup && !text.startsWith('/estado') && !text.startsWith('admin_')) {
    return []; // Return empty array to stop workflow execution
}

return [{
    json: {
        update_id: elemento.update_id || 0,
        chat_id,
        user_id,
        first_name,
        text,
        isGroup,
        callback_query_id
    }
}];

