const items = $input.all();
const chat_id = $('Extraer datos').first().json.chat_id;

if(items.length === 0 || !items[0].json || !items[0].json.id_pedido) {
  return [{json: { chat_id, mensaje: "No tienes pedidos anteriores. ¡Anímate a hacer tu primer pedido! 🍔" }}];
}

let msj = "📋 *Tu Historial de Pedidos:*\n\n";
const ultimos = items.slice(-5).reverse();
for(let item of ultimos) {
  const p = item.json;
  msj += `🛒 Pedido: ${p.id_pedido}\n📅 Fecha: ${p.fecha || ''} ${p.hora || ''}\n💵 Total: $${Number(p.total_pago).toLocaleString('es-CO')}\n📌 Estado: *${p.estado}*\n\n`;
