const items = $input.all();
if(items.length === 0 || !items[0].json.id_pedido) {
  return [{json: {mensaje: "No tienes ningún pedido reciente."}}];
}
const p = items[items.length - 1].json;
let msj = `🔎 *Estado de tu pedido actual*\n\n🛒 Pedido: ${p.id_pedido}\n📌 Estado: *${p.estado}*\n💵 Total: ${p.total_pago}\n\n¡Te avisaremos cuando haya actualizaciones!`;
return [{json: {mensaje: msj}}];

const text = $input.all()[0].json.text || "";
const chatId = $input.all()[0].json.chat_id || "";

const partes = text.trim().split('_');
const action = partes[1] || "";
const id_pedido = partes.slice(2).join('_').trim() || "";

let estado = "";
if (action.startsWith('prep')) estado = "En preparación";
else if (action.startsWith('listo')) estado = "Listo para entregar";
else if (action.startsWith('ent')) estado = "Entregado";
else estado = "Desconocido";

return [{json: { id_pedido, estado, original_chat_id: chatId }}];

const prev = $('Preparar Prompt IA').first().json;
try {
    const respuesta = $input.first().json;
    let content;
    if (respuesta.choices && respuesta.choices[0] && respuesta.choices[0].message) {
        let rawText = respuesta.choices[0].message.content;

        // Find the first { and last } to extract JSON
        const startIndex = rawText.indexOf('{');
        const endIndex = rawText.lastIndexOf('}');

        if (startIndex !== -1 && endIndex !== -1 && endIndex >= startIndex) {
            const jsonString = rawText.substring(startIndex, endIndex + 1);
            content = (typeof jsonString === 'string' ? JSON.parse(jsonString) : jsonString);
        } else {
            throw new Error("No JSON object found in response");
        }
    } else {
        throw new Error("No choices in response");
    }

    return [{json: {
        intencion: content.intencion || 'saludo',
        respuesta_amable: content.respuesta_amable || '¡Hola!',
        productos: content.productos || [],
        chatId: prev.chatId,
        userId: prev.userId,
        firstName: prev.firstName,
        textoUsuario: prev.textoUsuario
    }}];
} catch(e) {
    return [{json: {
        intencion: 'saludo',
        respuesta_amable: 'Disculpa, tuve un pequeño inconveniente técnico procesando tu mensaje. Por favor, utiliza los botones del menú para continuar con tu pedido.',
        productos: [],
        chatId: prev.chatId,
        userId: prev.userId,
        firstName: prev.firstName,
        textoUsuario: prev.textoUsuario,
        error: e.message
    }}];
}

const menuItems = $('Leer MENU AI').all().map(i => i.json);
const iaData = $('Extraer IA JSON').first().json;
const productosIA = iaData.productos || [];
const userId = iaData.userId;
const chatId = iaData.chatId;

let carrito = [];
try {
    const sesion = $('Leer sesion AI').all();
    if (sesion.length > 0 && sesion[0].json && sesion[0].json.carrito_temporal && sesion[0].json.carrito_temporal !== '' && sesion[0].json.carrito_temporal !== '[]') {
        carrito = JSON.parse(sesion[0].json.carrito_temporal);
    }
} catch(e) { carrito = []; }

let added = [];
let insuficientes = [];
let agotados = [];
let notFound = [];

for (const p_ia of productosIA) {
    const producto = menuItems.find(m => m.id_producto === p_ia.id_producto);
    if (!producto) {
        notFound.push(p_ia.id_producto || 'Desconocido');
        continue;
    }

    const qty = Number(p_ia.cantidad) || 1;
    const stockDisponible = (producto.stock === '' || producto.stock === undefined || producto.stock === null) ? 999 : Number(producto.stock);

    const idx = carrito.findIndex(i => i.id === producto.id_producto);
    const cantEnCarrito = idx >= 0 ? carrito[idx].cantidad : 0;

    if (stockDisponible <= 0) {
        agotados.push(producto.nombre);
    } else if (cantEnCarrito + qty > stockDisponible) {
        const disponibleParaAgregar = stockDisponible - cantEnCarrito;
        if (disponibleParaAgregar > 0) {
            if (idx >= 0) {
                carrito[idx].cantidad += disponibleParaAgregar;
            } else {
                carrito.push({
                    id: producto.id_producto,
                    nombre: producto.nombre,
                    cantidad: disponibleParaAgregar,
                    precio: Number(producto.precio || 0)
                });
            }
            insuficientes.push(`${producto.nombre} (sólo agregué ${disponibleParaAgregar} por stock disponible de ${stockDisponible})`);
        } else {
            insuficientes.push(`${producto.nombre} (ya tienes el máximo de ${stockDisponible} en el carrito)`);
        }
    } else {
        if (idx >= 0) {
            carrito[idx].cantidad += qty;
        } else {
            carrito.push({
                id: producto.id_producto,
                nombre: producto.nombre,
                cantidad: qty,
                precio: Number(producto.precio || 0)
            });
        }
        added.push(`${producto.nombre} x${qty}`);
    }
}

const subtotal = carrito.reduce((s, i) => s + (i.precio * i.cantidad), 0);
const iva = Math.round(subtotal * 0.19);
const granTotal = subtotal + iva;
const detalle = carrito.map(i => '• ' + i.nombre + ' x' + i.cantidad + ' = $' + (i.precio * i.cantidad).toLocaleString('es-CO')).join('\\n');

let mensaje = '';
if (added.length > 0) {
    mensaje += '✅ *Añadí al carrito:*\\n- ' + added.join('\\n- ');
}
if (insuficientes.length > 0) {
    if (mensaje) mensaje += '\\n\\n';
    mensaje += '⚠️ *Stock limitado:*\\n- ' + insuficientes.join('\\n- ');
}
if (agotados.length > 0) {
    if (mensaje) mensaje += '\\n\\n';
    mensaje += '❌ *Agotado(s):*\\n- ' + agotados.join('\\n- ');
}
if (notFound.length > 0) {
    if (mensaje) mensaje += '\\n\\n';
    mensaje += '🔍 *No encontrado(s) en menú:*\\n- ' + notFound.join('\\n- ');
}

if (added.length > 0 || insuficientes.some(x => x.includes("agregué"))) {
    if (mensaje) mensaje += '\\n\\n';
    mensaje += '🛒 *Tu carrito:*\\n' + detalle + '\\n\\n🧾 Subtotal: $' + subtotal.toLocaleString('es-CO') + '\\n💳 IVA (19%): $' + iva.toLocaleString('es-CO') + '\\n💰 *Total a pagar: $' + granTotal.toLocaleString('es-CO') + '*';
} else {
    if (!mensaje) {
        mensaje = '❌ No encontré esos productos en el menú.\\nUsa /menu para ver lo que tenemos disponible. 🍽️';
    } else {
        mensaje += '\\n\\nUsa /menu para ver otras opciones disponibles. 🍽️';
    }
}

const teclado = JSON.stringify({ inline_keyboard: [
    [{ text: "🛒 Ver Carrito", callback_data: "/carrito" }, { text: "➕ Seguir Comprando", callback_data: "/menu" }],
    [{ text: "✅ Confirmar Pedido", callback_data: "/pagar" }]
]});

return [{json: { chatId, userId, carritoJson: JSON.stringify(carrito), mensaje, teclado }}];

