// Build menu grouped by category with numbers within each category
const categorias = {};
menuItems.forEach(p => {
    if (!categorias[p.categoria]) categorias[p.categoria] = [];
    categorias[p.categoria].push(p);
});

let menuTexto = "";
for (const [cat, prods] of Object.entries(categorias)) {
    menuTexto += "\n== " + cat.toUpperCase() + " ==\n";
    prods.forEach((p, idx) => {
        menuTexto += (idx + 1) + ". " + p.nombre + " (ID: " + p.id_producto + ", $" + p.precio + ")\n";
    });
}

const systemPrompt = "Eres un asistente de cafeteria amigable.\n\nMENU DISPONIBLE:\n" + menuTexto + "\n" +
"El usuario estaba viendo la categoria: " + pantallaActual.toUpperCase() + ".\n" +
"REGLAS:\n" +
"1. Si saluda: intencion=saludo, respuesta_amable=saludo con nombre.\n" +
"2. Si pide pagar, confirmar o enviar el pedido (ej: 'quiero pagar', 'confirmar'): intencion=pagar, respuesta_amable=''.\n" +
"3. Si pide productos por nombre, numero o descripcion: intencion=pedir.\n" +
"   IMPORTANTE: Si pide un numero ('quiero el 1'), Mapealo al ID del producto #1 de la categoria que estaba viendo (" + pantallaActual.toUpperCase() + "). Convierte texto a numeros (ej: 'uno del 2').\n" +
"   Si especifica otra categoria ('el 1 de snacks'), mapealo a ese.\n" +
"4. Si no entiendes: intencion=saludo.\n\n" +
"ESTRICTO: Responde EXCLUSIVAMENTE con el objeto JSON. NADA de texto antes ni despues. NO uses markdown. SOLO el JSON:\n" +
"{\n" +
"  \"intencion\": \"saludo\" | \"pedir\" | \"pagar\",\n" +
"  \"respuesta_amable\": \"texto\",\n" +
"  \"productos\": [{\"id_producto\": \"BEB-001\", \"cantidad\": 1}]\n" +
"}";

const userMessage = "Cliente: " + firstName + ". Mensaje: " + textoUsuario;

return [{json: { systemPrompt, userMessage, chatId, userId, firstName, textoUsuario, pantallaActual }}];

